def create_first_versions(apps, schema_editor):
    """O estado atual de cada anamnese vira a versão 1. O que ela teve antes disso já foi sobrescrito."""
    Anamnesis = apps.get_model("clinical", "Anamnesis")
    Version = apps.get_model("clinical", "AnamnesisVersion")
    VersionAnswer = apps.get_model("clinical", "AnamnesisVersionAnswer")
    for anamnesis in Anamnesis.objects.select_related("patient"):
        version = Version.objects.create(
            anamnesis=anamnesis,
            number=1,
            notes=anamnesis.notes,
            saved_by_id=anamnesis.patient.owner_id,  # só o dono do paciente salva a anamnese
            saved_at=anamnesis.updated_at,
        )
        VersionAnswer.objects.bulk_create(
            VersionAnswer(version=version, question_id=a.question_id, question_text=a.question.text, answer=a.answer, detail=a.detail)
            for a in anamnesis.answers.select_related("question")
        )


